export function getPageMeta(path) {
  const data = SEO[path];
  if (!data) throw new Error('No SEO row for path: ' + path);
  return {
    title: data.title,
    description: data.description,
    alternates: { canonical: data.canonical },
    keywords: [data.focusKeyword, ...data.secondaryKeywords],
    openGraph: { title: data.ogTitle, description: data.ogDescription, url: data.canonical, siteName: 'RentalForCar', type: 'website' },
    twitter: { card: 'summary_large_image', title: data.ogTitle, description: data.ogDescription },
  };
}

export const ALL_PATHS = Object.keys(SEO);
